import { describe, expect, it } from 'vitest';
import { readFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';
import { analysePackage, parsePackage } from '../src/fabrication/package.js';
import { PACKAGE_KEYS } from '../src/fabrication/packages.js';
import { fitterObservations } from '../src/fabrication/fitAdapter.js';
import type { FabricationPackage } from '../src/fabrication/types.js';

/**
 * Design-observation fabrication (设计观测制作) evidence.
 *
 * These assertions verify the persisted packages (data/fabrication/*.json,
 * regenerated by `npm run gen:fabrication`) really exist and really reproduce
 * their declared conventions when run through the measurement-point fit kernel.
 * They also pin the two structural claims the subsystem is built to demonstrate:
 *
 *   1. the fitter is handed ONLY observations — truth/fixture/reliability never
 *      reach the fit, so the reconstruction cannot be a copy of the truth;
 *   2. when two point clouds have similar residual, the per-edge mating coverage
 *      — not the residual — decides which sharp-edge segment still needs work.
 */

const ROOT = resolve(__dirname, '..');

function load(key: string): FabricationPackage {
  const path = resolve(ROOT, 'data/fabrication', key + '.json');
  expect(existsSync(path), `资料包文件应真实存在: data/fabrication/${key}.json（运行 npm run gen:fabrication）`).toBe(true);
  return parsePackage(readFileSync(path, 'utf8'));
}

const packages = Object.fromEntries(PACKAGE_KEYS.map((k) => [k, load(k)])) as Record<(typeof PACKAGE_KEYS)[number], FabricationPackage>;

describe('fabrication packages exist and carry provenance', () => {
  it('every canonical package is a real, schema-valid file', () => {
    for (const key of PACKAGE_KEYS) {
      const pkg = packages[key];
      expect(pkg.schemaVersion).toBe('1.0.0');
      expect(pkg.observations.length).toBeGreaterThan(100);
      expect(pkg.fixture.points.length).toBeGreaterThan(100);
      expect(pkg.truth.grid.points.length).toBe(81 * 81);
    }
  });

  it('records fabrication provenance and parameters', () => {
    for (const key of PACKAGE_KEYS) {
      const p = packages[key].provenance;
      expect(p.generator).toBe('design-observation-fabricator');
      expect(p.seed).toBe(7007);
      expect(p.noiseSigma).toBeGreaterThan(0);
      expect(p.notes.length).toBeGreaterThan(0);
      expect(p.truthSpecId).toBe(packages[key].truth.spec.id);
    }
  });

  it('every observation carries parameter labels and reliability info', () => {
    const pkg = packages['analytic-refined'];
    for (const o of pkg.observations) {
      expect(Number.isFinite(o.u)).toBe(true);
      expect(Number.isFinite(o.v)).toBe(true);
      expect(o.reliability.sigma).toBeGreaterThan(0);
      expect(o.reliability.labelConfidence).toBeGreaterThan(0);
      expect(o.reliability.status === 'accepted' || o.reliability.status === 'outlier').toBe(true);
    }
    // some points were deliberately injected as outliers for the robust kernel
    expect(pkg.observations.filter((o) => o.reliability.status === 'outlier').length).toBe(4);
  });
});

describe('the fitter sees only measurements (no truth leakage)', () => {
  it('strips reliability and provenance before fitting', () => {
    const pkg = packages['analytic-refined'];
    const stripped = fitterObservations(pkg.observations);
    for (const o of stripped) {
      expect('reliability' in o).toBe(false);
      // the fit input must not carry the injected-outlier ground truth
      expect(Object.keys(o).sort()).toEqual(['id', 'normal', 'passId', 'point', 'probeId', 'side', 'u', 'v']);
    }
  });

  it('reconstructs from observations alone, not from the saved truth grid', () => {
    // A fit of the observations must pass its own residual check yet NOT equal the
    // truth control points: the package never stores a "solution" surface, so
    // agreement with the truth can only come from the data.
    const pkg = packages['analytic-refined'];
    const { analysis } = analysePackage(pkg);
    expect(analysis.fitRms).toBeLessThan(0.0012);
    // the fit is a genuine measurement result, so it carries finite residual
    // spread; an exact copy of the truth would be ~0.
    expect(analysis.truthError.rms).toBeGreaterThan(1e-5);
  });
});

describe('reconstruction matches each package declared conventions', () => {
  for (const key of PACKAGE_KEYS) {
    it(`${key}: conventions pass`, () => {
      const { conventions } = analysePackage(packages[key]);
      const failed = conventions.checks.filter((c) => !c.ok);
      expect(failed.map((c) => `${c.id}: ${c.detail}`)).toEqual([]);
    });
  }
});

describe('mating coverage — not residual — decides which edge needs measurement', () => {
  const analyticRefined = analysePackage(packages['analytic-refined']);
  const sectionRefined = analysePackage(packages['section-refined']);

  it('section-refined has a LOWER residual yet FAR WORSE mating coverage', () => {
    // the decisive boundary condition: residual alone cannot tell the methods apart
    expect(sectionRefined.analysis.fitRms).toBeLessThan(analyticRefined.analysis.fitRms);
    expect(sectionRefined.analysis.mating.coverage).toBeLessThan(analyticRefined.analysis.mating.coverage - 0.2);
  });

  it('distinguishes "sample an analytic surface" from "assemble from sections"', () => {
    // both were measured at the apex row (same refined table), so the difference is
    // purely methodology; the advice must differ accordingly
    expect(analyticRefined.analysis.edgeAdvice.advice).toBe('none');
    expect(sectionRefined.analysis.edgeAdvice.advice).toBe('method-review');
  });

  it('a sparse table with no apex row asks for MORE MEASUREMENT at the weakest lobe', () => {
    const coarse = analysePackage(packages['analytic-coarse']);
    expect(coarse.analysis.edgeAdvice.advice).toBe('add-measurement');
    // the weakest segment is a real per-lobe segment, and it is genuinely weak
    expect(coarse.analysis.mating.worstSegment).not.toBeNull();
    expect(coarse.analysis.mating.worstSegment!.coverage).toBeLessThan(0.9);
  });

  it('the two sampling tables differ ONLY near the sharp ridge', () => {
    const a = packages['analytic-coarse'];
    const b = packages['analytic-refined'];
    expect(b.observations.length).toBeGreaterThan(a.observations.length);
    // outside the ridge band both tables must sample the same parameter grid
    const outside = (pkg: FabricationPackage) =>
      new Set(
        pkg.observations
          .filter((o) => Math.abs(o.v - pkg.truth.spec.ridgeV) > 0.09)
          .map((o) => `${o.u.toFixed(4)}:${o.v.toFixed(4)}`),
      );
    const ua = outside(a);
    const ub = outside(b);
    expect(ua.size).toBe(ub.size);
    for (const k of ua) expect(ub.has(k)).toBe(true);
  });
});

describe('robust fitting covers non-uniform sampling and outliers', () => {
  it('downweights the injected normal-outliers', () => {
    const { analysis } = analysePackage(packages['analytic-refined']);
    expect(analysis.outliers.injected).toBe(4);
    expect(analysis.outliers.downweighted).toBeGreaterThanOrEqual(3);
  });

  it('verifies with both fit error and observation coverage', () => {
    const { analysis } = analysePackage(packages['analytic-refined']);
    expect(analysis.fitRms).toBeLessThan(analysis.truthError.rms + 0.001); // fit error sane
    expect(analysis.coverage.occupancy).toBeGreaterThan(0.9); // coverage verified
    expect(analysis.coverage.ridgeBandCount).toBeGreaterThan(0);
  });
});
